import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams } from "react-router-dom";

const AdmInfCurso = () => {
  const { id } = useParams(); // Captura o ID da URL
  const [curso, setCurso] = useState(null);

  useEffect(() => {
    const fetchCurso = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/cursos/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setCurso(dados);
        } else {
          console.error("Erro ao buscar curso");
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    fetchCurso();
  }, [id]);

  if (!curso) {
    return <p className="text-center mt-4">Carregando curso...</p>;
  }

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <h2 className="mt-4">{curso.nome}</h2>
      <p><strong>Nível:</strong> {curso.nivel}</p>
      <p><strong>Período:</strong> {curso.periodo}</p>
      <p><strong>Área:</strong> {curso.area}</p>
      <p><strong>Professor:</strong> {curso.professor}</p>
      <h4>Alunos:</h4>
      <ul className="list-group">
        {curso.alunos.map((aluno, index) => (
          <li key={index} className="list-group-item">
            {aluno}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default AdmInfCurso;
